import React, { useState, useEffect } from 'react';
import { getAlerts, getAlertStats, getAllTopics } from '../api/api';

function AlertsPage() {
  // All my state variables
  const [alerts, setAlerts] = useState([]);
  const [stats, setStats] = useState(null);
  const [topics, setTopics] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // Filter states
  const [severityFilter, setSeverityFilter] = useState('');
  const [topicFilter, setTopicFilter] = useState('');

  // Page state
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalItems, setTotalItems] = useState(0);

  // This function gets all the data from the backend
  const loadEverything = async () => {
    setLoading(true);
    setError("");
    try {
      // Beginners usually call APIs one by one instead of using Promise.all
      const alertsResponse = await getAlerts({
        page: page,
        pageSize: 15,
        severity: severityFilter !== "" ? severityFilter : null,
        topic: topicFilter !== "" ? topicFilter : null
      });
      setAlerts(alertsResponse.data);
      setTotalPages(alertsResponse.pagination.total_pages);
      setTotalItems(alertsResponse.pagination.total_count);

      const topicsResponse = await getAllTopics();
      setTopics(topicsResponse.topics);

      const statsResponse = await getAlertStats();
      setStats(statsResponse);

      setLoading(false);
    } catch (err) {
      setError("Something went wrong with the API");
      setLoading(false);
    }
  };

  // Run this when the page loads or filters change
  useEffect(() => {
    loadEverything();
  }, [page, severityFilter, topicFilter]);

  // Handle changing filters
  const changeSeverity = (e) => {
    setSeverityFilter(e.target.value);
    setPage(1); // reset to page 1
  };

  const changeTopic = (e) => {
    setTopicFilter(e.target.value);
    setPage(1); // reset to page 1
  };

  return (
    <div style={{ padding: '20px' }}>
      <h1>Alerts</h1>
      <p>See all the sensor problems here</p>

      {/* Stats section */}
      {stats != null && (
        <div style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
          <div style={{ border: '1px solid gray', padding: '10px' }}>
            Total: {stats.total_alerts}
          </div>
          <div style={{ border: '1px solid red', padding: '10px', color: 'red' }}>
            Critical: {stats.critical_alerts}
          </div>
          <div style={{ border: '1px solid orange', padding: '10px', color: 'orange' }}>
            Warnings: {stats.warning_alerts}
          </div>
        </div>
      )}

      {/* Dropdowns for filtering */}
      <div style={{ marginBottom: '20px' }}>
        <span>Filter by: </span>
        <select value={severityFilter} onChange={changeSeverity}>
          <option value="">All</option>
          <option value="CRITICAL">Critical</option>
          <option value="WARNING">Warning</option>
        </select>

        <select value={topicFilter} onChange={changeTopic} style={{ marginLeft: '10px' }}>
          <option value="">All Devices</option>
          {topics.map((t) => (
            <option key={t} value={t}>{t}</option>
          ))}
        </select>

        <button onClick={loadEverything} style={{ marginLeft: '10px' }}>Refresh</button>
      </div>

      {/* Show loading, error, or the list */}
      {loading == true ? (
        <p>Loading the alerts...</p>
      ) : error != "" ? (
        <p style={{ color: 'red' }}>{error}</p>
      ) : (
        <div>
          {alerts.map((alert) => (
            <div key={alert.id} style={{ border: '1px solid #ccc', marginBottom: '10px', padding: '10px' }}>
              <div style={{ fontWeight: 'bold' }}>📍 {alert.topic}</div>
              <div>Severity: {alert.severity}</div>
              <div>Time: {new Date(alert.created_at).toLocaleString()}</div>

              <div style={{ marginTop: '5px' }}>
                <strong>Issues:</strong> {alert.violated_keys.join(", ")}
              </div>
            </div>
          ))}

          {/* Pagination buttons */}
          <div style={{ marginTop: '20px' }}>
            <button disabled={page == 1} onClick={() => setPage(page - 1)}>Back</button>
            <span style={{ margin: '0 10px' }}>Page {page} of {totalPages}</span>
            <button disabled={page == totalPages} onClick={() => setPage(page + 1)}>Next</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default AlertsPage;
